from lib import *
S = SS('c13')
steps = [
    step("构建 v1 命名为 bwlab-c13:a,镜像 ID 是 f5b5f81ecbb1…(完整形式 sha256: 加 64 位十六进制)。在这个镜像存储(containerd)里,.Id 与 .Descriptor.digest 相同——镜像 ID 就是顶层 manifest 的摘要。没推送过的镜像,RepoDigests 里也有一项 bwlab-c13@sha256:f5b5…。再构建 v2 命名为 bwlab-c13:b,ID 是 1d96e82a084a…。", t=tl(S(1)), done=lidx(S(1), '.Id 和 .Descriptor.digest'), mark=lidx(S(1), 'RepoDigests'), kv=KV([['bwlab-c13:a', 'ID f5b5f81ecbb1…(v1)'], ['bwlab-c13:b', 'ID 1d96e82a084a…(v2)'], ['ID 与 digest', '这里是同一个值']], ['ID 与 digest'])),
    step("docker tag bwlab-c13:b bwlab-c13:a 把 a 这个名字挪到了 v2 上:现在 a 与 b 的 ID 相同(都是 1d96e82a084a…)。原来的 v1 变成 <untagged> 出现在 docker image ls -a 里(ID f5b5f81ecbb1),按旧 ID 运行 docker run --pull=never f5b5f81ecbb1,退出码 0,输出 v1——镜像还在,只是没有名字了。", t=tl(S(2)), done=lidx(S(2), '按旧 ID 运行'), mark=lidx(S(2), '<untagged>'), kv=KV([['tag 之后', 'a 与 b 指向同一个 ID'], ['v1', '变成 <untagged>,仍可按 ID 运行']], ['v1'])),
    step("name@digest 的引用在本机的表现:被挪走名字的 v1,docker run --pull=never bwlab-c13@sha256:f5b5… 退出码 125,No such image;当前叫 bwlab-c13 的 v2,bwlab-c13@sha256:1d96… 退出码 0,输出 v2;随便写的全零摘要也是 125。本机上 name@digest 要这个镜像此刻还带着 bwlab-c13 这个名字才找得到,按 ID 才能找到没名字的镜像。", t=tl(S(3)), done=lidx(S(3), 'bwlab-c13@sha256:1d96e82a084a'), mark=lidx(S(3), 'bwlab-c13@sha256:f5b5f81ecbb1', '不存在的摘要'), kv=KV([['无名字的 v1', 'name@digest → 找不到(125)'], ['有名字的 v2', 'name@digest → 能运行'], ['全零摘要', '找不到(125)']], ['无名字的 v1'])),
    step("重新构建同一个 tag(docker build,不是 docker tag)的结果不同:bwlab-c13:c 先后构建两次,ID 8656f6b6bd5f → 1c31d8e2e739,按第一次的 ID 运行,退出码 125,No such image;docker image ls -a 里的 <untagged> 也只有之前 docker tag 留下的 f5b5f81ecbb1,没有第一次构建的那个。重新构建会把同名的老镜像直接替换掉(我没有深究是哪一层做的)。", t=tl(S(4)), done=lidx(S(4), '先后构建两次'), mark=lidx(S(4), '按第一次的 ID 运行'), kv=KV([['docker tag 挪名字', '旧镜像变 <untagged>,还在'], ['docker build 同名', '旧镜像不在了,按 ID 也找不到']], ['docker build 同名'])),
    step("同一个 Dockerfile、同样的内容,--no-cache 构建两次(中间隔 1.1 秒):镜像 ID 886d739dd530 与 cfd9225cfd6e,不同。RootFS.Layers 共 2 层:alpine 基础层相同,RUN 产生的那一层不同——同样的命令产出的层内容不是逐字节一致的(我没有逐个文件比较,推测是文件时间戳)。", t=tl(S(5)), done=lidx(S(5), 'alpine 基础层相同吗?True'), mark=lidx(S(5), '相同吗?False'), b=bars([['基础层相同 (层数)', 1, '1'], ['RUN 层相同 (层数)', 0, '0']], 2, done=[0], mark=[1]), kv=KV([['两次 --no-cache', 'ID 不同'], ['基础层', '相同'], ['RUN 层', '不同']], ['RUN 层'])),
    step("全部命中缓存的重复构建,ID 也在变:默认情况下连续构建三次,ID 是 f36ba2a729ba、2ef9bec6124a、4ddb08e30de0,三个互不相同,层却都相同;加 --provenance=false --sbom=false,三次都是 af13472dcb8a。c11 里看到过,默认构建会往索引里加 attestation manifest;ID 是顶层 manifest 的摘要,所以我推测是证明的内容每次不同带来的变化(没有单独验证是 provenance 还是 sbom 起作用)。", t=tl(S(6)), done=lidx(S(6), '--provenance=false'), mark=lidx(S(6), '默认(带 provenance 证明)'), b=bars([['默认:三次 ID 的种类', 3, '3'], ['关掉证明:三次 ID 的种类', 1, '1']], 3, done=[1], mark=[0]), kv=KV([['默认构建', '三次 ID 各不相同,层相同'], ['--provenance=false --sbom=false', '三次 ID 一致'], ['推测', '证明内容每次不同']], ['推测'])),
]
A = mkartc('c13', 13, 'Docker,镜像摘要,digest,镜像ID,tag,provenance,真实验证,动画演示',
    '在 Docker Engine 29.8.2(containerd 镜像存储)里实测镜像的 tag、ID 与 digest:镜像 ID 就是顶层 manifest 摘要;docker tag 挪走名字后旧镜像变成 untagged(无名字)但仍可按 ID 运行,docker build 同名则直接替换;同一个 Dockerfile 的 --no-cache 两次构建 ID 不同;全缓存重复构建默认也得到 3 个不同的 ID,关掉 provenance 后三次一致。',
    '同一个 tag 为什么会指向不同的内容?这篇用本机构建的镜像实际看:镜像 ID 和 digest 是什么关系,docker tag 和重新 docker build 对旧镜像的处理有什么不同,name@digest 在本机什么时候找得到,以及“同一个 Dockerfile 是不是同一个镜像”。',
    [('f5b5… vs 1d96…', 'v1 和 v2 的镜像 ID(也是顶层 manifest 摘要),tag 挪走之后 v1 还能按 ID 运行'), ('3 个 vs 1 个 ID', '全缓存重复构建三次:默认得到 3 个不同的 ID,关掉 provenance 和 sbom 后只有 1 个'), ('退出码 125', 'name@digest 引用一个已经没有这个名字的镜像:No such image')],
    [('ID 与 digest', '<p>构建 v1 命名为 <code>bwlab-c13:a</code>,<code>.Id</code> 与 <code>.Descriptor.digest</code> 是同一个值;<code>RepoDigests</code> 里即使没推送过也有一项 <code>bwlab-c13@sha256:…</code>。这是 containerd 镜像存储下的表现;换成经典的存储驱动,ID 的含义是否一样,本文没有测。</p>'),
     ('docker tag 挪名字', '<p><code>docker tag bwlab-c13:b bwlab-c13:a</code> 之后,两个名字指向同一个 ID;原来 a 指向的 v1 变成 <code>&lt;untagged&gt;</code>,但镜像还在,<code>docker run --pull=never</code> 加上旧 ID 能跑出 v1。同一个 tag 在不同时间指向不同内容,就是这么来的。</p>'),
     ('name@digest 在本机', '<p>被挪走名字的 v1,用 <code>bwlab-c13@sha256:f5b5…</code> 引用,<code>--pull=never</code> 下报 No such image(退出码 125);当前叫 bwlab-c13 的 v2 用它自己的摘要引用就能运行。本机的 name@digest 解析要求这个镜像此刻还带着这个名字。摘要在仓库里“钉住”内容的作用,本文没有实验(需要 registry)。</p>'),
     ('docker build 同名', '<p>重新构建同一个 tag 和 <code>docker tag</code> 挪名字不一样:这个环境里旧镜像没有留下 <code>&lt;untagged&gt;</code>,按旧 ID 运行也找不到。我没有查是哪一层把它删掉的,只记录观察到的结果。</p>'),
     ('同一个 Dockerfile', '<p>两次 <code>--no-cache</code> 构建同样的 Dockerfile,镜像 ID 不同,alpine 基础层相同,RUN 产生的层不同。要得到可复现的构建,需要额外控制时间戳之类的输入(本文没有测怎么做)。</p>'),
     ('命中缓存也会变', '<p>三次全缓存的构建,默认得到 3 个不同的镜像 ID,但层完全一致;加上 <code>--provenance=false --sbom=false</code> 后三次 ID 相同。结合之前 c11 看到的 attestation manifest,我推测是附带的构建证明让顶层摘要变了,没有单独验证是 provenance 还是 sbom 起作用。想用摘要比较两个镜像“内容是否相同”时,这点要小心。</p>')],
    steps,
    [ENV_C + '。基础镜像 alpine:3.20 用 dpull.py 下载后 docker load;所有镜像在本机构建,没有推送;ID 取 docker image inspect 的 .Id,层取 .RootFS.Layers;docker run 用 --pull=never 避免去访问 registry;实验后已删除所有镜像',
     '没有验证:推送到仓库后的摘要与 RepoDigests、经典存储驱动下的 ID 含义、docker pull 时摘要如何校验、缓存命中的构建 ID 变化到底来自 provenance 还是 sbom、用 SOURCE_DATE_EPOCH 等方式得到可复现构建'],
    '镜像摘要与标签')
